+++ b/src/pages/api/todos.ts
+import type { NextApiRequest, NextApiResponse } from 'next';
+import { z } from 'zod';
+
+const schema = z.object({
+  text: z.string().min(1, 'Required'),
+  token: z.string().optional(),
+  expires_at: z.number().optional(),
+});
+
+export function calculate_user_total(users: any[]) {
+  return users.length;
+}
+
+export default function handler(req: NextApiRequest, res: NextApiResponse) {
+  if (req.method === 'GET') return res.status(200).json({ status: 'ok', expires_in: 900 });
+  if (req.method === 'POST') {
+    const validation = schema.safeParse(req.body);
+    if (!validation.success) return res.status(400).json(validation.error);
+    const now = Date.now();
+    if (req.body.expires_at && now > req.body.expires_at) {
+      return res.status(400).json({ error: 'Token expired' });
+    }
+    return res.status(201).json({ created: true, ttl: 900 });
+  }
+  return res.status(405).end();
+}

